-- PNeX baseline schema, SQLite (hobbyist tier) (0.1.0, cut 2026-10-09).
-- Generated from the pre-release migrations, then cleaned: legacy
-- plaintext/AI-connector leftovers removed, compatibility columns dropped
-- (device metadata, host ws_ssl, build success flag). Every later change
-- goes in a new migration (docs/architecture/migrations.md).

CREATE TABLE "users" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "idp_sub" varchar(64) NULL, "email" varchar(255) NOT NULL UNIQUE, "full_name" varchar(255) NULL , "platform_admin" boolean NOT NULL DEFAULT FALSE);
CREATE TABLE "subscription_tiers" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "max_sensor_devices" integer NOT NULL, "max_actuator_devices" integer NOT NULL, "max_mixed_devices" integer NOT NULL, "min_build_interval_secs" integer NOT NULL DEFAULT 900, "data_retention_secs" integer NULL , "max_telemetry_mb" integer NULL);
CREATE TABLE "organizations" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL UNIQUE, "subscription_tier_id" integer NULL, "data_retention_days" integer NULL, "ai_retention_days" integer NULL, FOREIGN KEY ("subscription_tier_id") REFERENCES "subscription_tiers" ("id") ON DELETE SET NULL ON UPDATE NO ACTION );
CREATE TABLE "organization_members" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "role" enum_text NOT NULL DEFAULT 'viewer', "user_id" integer NOT NULL, "org_id" integer NOT NULL, FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE "user_profiles" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(10) NOT NULL DEFAULT 'en', "timezone" varchar(50) NOT NULL DEFAULT 'UTC', "date_format" varchar(20) NULL, "theme" enum_text NOT NULL DEFAULT 'auto', "preferences" jsonb_text NULL, "grafana_url" varchar(500) NULL, "user_id" integer NOT NULL, FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE UNIQUE INDEX uniq_users_idp_sub ON users (idp_sub) WHERE idp_sub IS NOT NULL;
CREATE UNIQUE INDEX uniq_organization_members_org_user ON organization_members (org_id, user_id);
CREATE UNIQUE INDEX uniq_user_profiles_user ON user_profiles (user_id);
CREATE TABLE "device_types" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE );
CREATE TABLE "device_capabilities" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL UNIQUE, "mode" enum_text NOT NULL DEFAULT 'input' );
CREATE TABLE "mcu_boards" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "soc" varchar(255) NOT NULL DEFAULT 'esp32', "details" jsonb_text NULL , "pretty_name" text NULL, "pio_board" text NULL);
CREATE TABLE "predefined_devices" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar NOT NULL UNIQUE, "pretty_name" varchar(255) NULL, "revision" varchar(50) NOT NULL DEFAULT '', "device_doc_url" varchar(1024) NULL, "prestashop_product_id" varchar(64) NULL, "prestashop_buy_url" varchar(1024) NULL, "byod_doc_url" varchar(1024) NULL, "image_source_url" varchar(1024) NULL, "stl_files_url" varchar(1024) NULL, "description" text NULL, "device_type_id" integer NOT NULL, "board_id" integer NOT NULL, "peripherals" jsonb_text NULL, "description_i18n" text NULL, FOREIGN KEY ("device_type_id") REFERENCES "device_types" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("board_id") REFERENCES "mcu_boards" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE "predefined_device_capabilities" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "predefined_device_id" integer NOT NULL, "device_capability_id" integer NOT NULL, CONSTRAINT "idx-predefined_device_capabilities-refs-pk" PRIMARY KEY ("predefined_device_id", "device_capability_id"), FOREIGN KEY ("predefined_device_id") REFERENCES "predefined_devices" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("device_capability_id") REFERENCES "device_capabilities" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE "device_registries" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "device_id" varchar(255) NOT NULL, "active" boolean NOT NULL DEFAULT FALSE, "allow_dynamic_measurements" boolean NOT NULL DEFAULT TRUE, "discovered_measurements" jsonb_text NULL, "max_unique_measurements" integer NOT NULL DEFAULT 100, "org_id" integer NOT NULL, "predefined_device_id" integer NOT NULL, "soc" text NULL, "board_id" integer NULL, "peripherals" jsonb_text NULL, "fw_version" text NULL, "ota_ready" boolean NULL, "announced_caps" jsonb_text NULL, "firmware_project_id" integer NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("predefined_device_id") REFERENCES "predefined_devices" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("firmware_project_id") REFERENCES "firmware_projects" ("id") ON DELETE SET NULL, FOREIGN KEY ("board_id") REFERENCES "mcu_boards" ("id") ON DELETE SET NULL );
CREATE TABLE "device_tokens" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token" varchar NOT NULL UNIQUE, "encryption_key" varchar(64) NOT NULL, "is_active" boolean NOT NULL DEFAULT TRUE, "device_registry_id" integer NOT NULL, FOREIGN KEY ("device_registry_id") REFERENCES "device_registries" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE UNIQUE INDEX uniq_device_registries_org_device_id ON device_registries (org_id, device_id);
CREATE UNIQUE INDEX uniq_device_tokens_device_registry ON device_tokens (device_registry_id);
CREATE UNIQUE INDEX uniq_predefined_devices_prestashop_product_id ON predefined_devices (prestashop_product_id) WHERE prestashop_product_id IS NOT NULL;
CREATE TABLE "fluid_mixtures" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "description" text NULL, "composition" jsonb_text NOT NULL, "org_id" integer NOT NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE "unit_conversions" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "from_unit" varchar(50) NOT NULL, "to_unit" varchar(50) NOT NULL, "conversion_type" enum_text NOT NULL, "multiplier" double NOT NULL DEFAULT 1, "offset" double NOT NULL DEFAULT 0, "expression" text NULL, "description" text NULL, "is_predefined" boolean NOT NULL DEFAULT FALSE, "global_id" uuid_text NULL, "version" integer NOT NULL DEFAULT 1, "category" varchar(50) NULL, "tags" jsonb_text NULL, "import_count" integer NOT NULL DEFAULT 0, "org_id" integer NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE SET NULL ON UPDATE NO ACTION );
CREATE TABLE "formulas" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "description" text NULL, "formula_type" enum_text NOT NULL, "expression" text NOT NULL, "result_unit" text NULL, "fluid_config" jsonb_text NULL, "is_predefined" boolean NOT NULL DEFAULT FALSE, "global_id" uuid_text NULL, "version" integer NOT NULL DEFAULT 1, "category" varchar(50) NULL, "tags" jsonb_text NULL, "import_count" integer NOT NULL DEFAULT 0, "compute_on_event" boolean NOT NULL DEFAULT FALSE, "cache_ttl" integer NOT NULL DEFAULT 60, "last_computed_at" timestamp_with_timezone_text NULL, "org_id" integer NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE SET NULL ON UPDATE NO ACTION );
CREATE TABLE "formula_data_sources" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "source_type" enum_text NOT NULL, "measurement_name" varchar(255) NULL, "constant_type" enum_text NULL, "constant_value" text NULL, "variable_name" varchar(100) NOT NULL, "sort_order" integer NOT NULL DEFAULT 0, "formula_id" integer NOT NULL, "device_registry_id" integer NULL, "unit_conversion_id" integer NULL, FOREIGN KEY ("formula_id") REFERENCES "formulas" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("device_registry_id") REFERENCES "device_registries" ("id") ON DELETE SET NULL ON UPDATE NO ACTION, FOREIGN KEY ("unit_conversion_id") REFERENCES "unit_conversions" ("id") ON DELETE SET NULL ON UPDATE NO ACTION );
CREATE UNIQUE INDEX uniq_fluid_mixtures_org_name ON fluid_mixtures (org_id, name);
CREATE UNIQUE INDEX uniq_unit_conversions_org_units ON unit_conversions (org_id, from_unit, to_unit) WHERE org_id IS NOT NULL;
CREATE UNIQUE INDEX uniq_unit_conversions_predefined_units ON unit_conversions (from_unit, to_unit) WHERE is_predefined;
CREATE UNIQUE INDEX uniq_formulas_global_id ON formulas (global_id) WHERE global_id IS NOT NULL;
CREATE UNIQUE INDEX uniq_formula_data_sources_formula_var ON formula_data_sources (formula_id, variable_name);
CREATE TABLE "build_records" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "device_id" varchar(255) NULL, "build_phase" varchar(255) NOT NULL DEFAULT 'queued', "firmware_bin_s3_key" varchar(255) NULL, "org_id" integer NOT NULL, "fw_version" text NULL, "ota_sha256" text NULL, "ota_size_bytes" integer NULL, "sources_fingerprint" text NULL, "firmware_revision_id" integer NULL, "failure_code" text NULL, "failure_detail" text NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("firmware_revision_id") REFERENCES "firmware_revisions" ("id") ON DELETE SET NULL );
CREATE TABLE "device_states" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "device_registry_id" integer NOT NULL UNIQUE, "last_seen_at" timestamp_with_timezone_text NOT NULL, FOREIGN KEY ("device_registry_id") REFERENCES "device_registries" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE "openobserve_orgs" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "org_id" integer NOT NULL UNIQUE, "o2_org" varchar(255) NOT NULL UNIQUE, "ingestion_token" text NULL, "status" enum_text NOT NULL DEFAULT 'pending', "last_error" text NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE "firmware_artifacts" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "key" varchar(255) NOT NULL UNIQUE, "bytes" blob NOT NULL, "size_bytes" integer NOT NULL, "sha256" varchar(64) NULL );
CREATE TABLE "device_capability_instances" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "device_registry_id" integer NOT NULL, "gpio" integer NOT NULL, "label" varchar(64) NOT NULL, "mode" varchar(32) NOT NULL, "config" jsonb_text NULL, "constraints_snapshot" jsonb_text NULL, "enabled" boolean NOT NULL DEFAULT TRUE, FOREIGN KEY ("device_registry_id") REFERENCES "device_registries" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE UNIQUE INDEX uniq_dci_device_gpio ON device_capability_instances (device_registry_id, gpio);
CREATE TABLE "flows" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "status" varchar(32) NOT NULL DEFAULT 'draft', "org_id" integer NOT NULL, "device_registry_id" integer NULL, "deployed_version_id" integer NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("device_registry_id") REFERENCES "device_registries" ("id") ON DELETE SET NULL ON UPDATE NO ACTION, FOREIGN KEY ("deployed_version_id") REFERENCES "flow_versions" ("id") ON DELETE SET NULL );
CREATE TABLE "flow_versions" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "version_number" integer NOT NULL, "graph" jsonb_text NOT NULL, "author" varchar(255) NULL, "note" text NULL, "flow_id" integer NOT NULL, FOREIGN KEY ("flow_id") REFERENCES "flows" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE UNIQUE INDEX uniq_flow_versions_flow_number ON flow_versions (flow_id, version_number);
CREATE TABLE "regulator_configs" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "node_id" varchar(64) NOT NULL, "kind" varchar(16) NOT NULL, "config" jsonb_text NOT NULL, "org_id" integer NOT NULL, "device_registry_id" integer NOT NULL, "flow_id" integer NOT NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("device_registry_id") REFERENCES "device_registries" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("flow_id") REFERENCES "flows" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE UNIQUE INDEX uniq_regulator_config_slot ON regulator_configs (device_registry_id, flow_id, node_id);
CREATE TABLE "media_assets" ( "id" uuid_text NOT NULL PRIMARY KEY, "org_id" integer NOT NULL, "kind" varchar(32) NOT NULL, "name" varchar(255) NOT NULL, "description" text NULL, "metadata" jsonb_text NULL, "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "current_version_id" uuid_text NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE, FOREIGN KEY ("current_version_id") REFERENCES "media_versions" ("id") ON DELETE SET NULL );
CREATE TABLE "media_versions" ( "id" uuid_text NOT NULL PRIMARY KEY, "asset_id" uuid_text NOT NULL, "org_id" integer NOT NULL, "version_number" integer NOT NULL, "filename" varchar(255) NOT NULL, "content_type" varchar(100) NOT NULL, "size_bytes" integer NOT NULL, "storage_key" text NOT NULL, "sha256" varchar(64) NULL, "metadata" jsonb_text NULL, "note" text NULL, "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY ("asset_id") REFERENCES "media_assets" ("id") ON DELETE CASCADE, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE );
CREATE UNIQUE INDEX uniq_media_versions_asset_number ON media_versions (asset_id, version_number);
CREATE INDEX idx_media_assets_org_kind ON media_assets (org_id, kind);
CREATE INDEX idx_media_assets_org_name ON media_assets (org_id, name);
CREATE INDEX idx_media_versions_org ON media_versions (org_id);
CREATE TABLE "stitch_jobs" ( "id" uuid_text NOT NULL PRIMARY KEY, "org_id" integer NOT NULL, "asset_id" uuid_text NOT NULL, "state" varchar(16) NOT NULL DEFAULT 'queued', "error" text NULL, "frames_total" integer NOT NULL, "frames_received" integer NOT NULL DEFAULT 0, "poses_json" jsonb_text NOT NULL, "hfov_deg" float NOT NULL, "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE, FOREIGN KEY ("asset_id") REFERENCES "media_assets" ("id") ON DELETE CASCADE );
CREATE INDEX idx_stitch_jobs_org ON stitch_jobs (org_id);
CREATE TABLE "dashboards" ( "id" uuid_text NOT NULL PRIMARY KEY, "org_id" integer NOT NULL, "name" varchar(255) NOT NULL, "description" text NULL, "current_version_number" integer NOT NULL DEFAULT 0, "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE );
CREATE TABLE "dashboard_versions" ( "id" uuid_text NOT NULL PRIMARY KEY, "dashboard_id" uuid_text NOT NULL, "version_number" integer NOT NULL, "layout" jsonb_text NOT NULL, "author" varchar(255) NULL, "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY ("dashboard_id") REFERENCES "dashboards" ("id") ON DELETE CASCADE );
CREATE TABLE "map_pins" ( "id" uuid_text NOT NULL PRIMARY KEY, "org_id" integer NOT NULL, "mode" varchar(16) NOT NULL, "latitude" real(9, 6) NULL, "longitude" real(9, 6) NULL, "x" real(10, 2) NULL, "y" real(10, 2) NULL, "label" varchar(255) NOT NULL, "emoji" varchar(16) NULL, "metadata" jsonb_text NULL, "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "location_detail" varchar(255) NULL, "preview_kind" varchar(255) NULL, "preview_id" varchar(255) NULL, CONSTRAINT "chk_map_pins_mode_coords" CHECK ((mode = 'geo' AND latitude IS NOT NULL AND longitude IS NOT NULL AND x IS NULL AND y IS NULL) OR (mode = 'plan' AND x IS NOT NULL AND y IS NOT NULL AND latitude IS NULL AND longitude IS NULL)), FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE );
CREATE UNIQUE INDEX uniq_dashboard_versions_doc_number ON dashboard_versions (dashboard_id, version_number);
CREATE INDEX idx_dashboards_org_name ON dashboards (org_id, name);
CREATE INDEX idx_map_pins_org_geo ON map_pins (org_id, latitude, longitude);
CREATE TABLE "device_positions" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "org_id" integer NOT NULL, "device_registry_id" integer NOT NULL UNIQUE, "device_id" varchar(255) NOT NULL, "latitude" real(9, 6) NOT NULL, "longitude" real(9, 6) NOT NULL, "altitude_m" real(8, 2) NULL, "accuracy_m" real(8, 2) NULL, "speed_mps" real(6, 2) NULL, "heading_deg" real(5, 1) NULL, "source" varchar(16) NOT NULL DEFAULT 'telemetry', "positioned_at" timestamp_with_timezone_text NOT NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("device_registry_id") REFERENCES "device_registries" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE INDEX idx_device_positions_org ON device_positions (org_id);
CREATE TABLE "viz_widget_library" ( "id" uuid_text NOT NULL PRIMARY KEY, "org_id" integer NOT NULL, "name" varchar(255) NOT NULL, "kind" varchar(16) NOT NULL, "config" jsonb_text NOT NULL, "created_by" integer NULL, "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE );
CREATE UNIQUE INDEX uniq_viz_widget_library_org_name ON viz_widget_library (org_id, name);
CREATE TABLE "tours" ( "id" uuid_text NOT NULL PRIMARY KEY, "org_id" integer NOT NULL, "name" varchar(255) NOT NULL, "description" text NULL, "mode" varchar(16) NOT NULL DEFAULT 'panorama', "share_token" varchar(64) NULL, "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "published_version_id" uuid_text NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE, FOREIGN KEY ("published_version_id") REFERENCES "tour_versions" ("id") ON DELETE SET NULL );
CREATE TABLE "tour_versions" ( "id" uuid_text NOT NULL PRIMARY KEY, "tour_id" uuid_text NOT NULL, "version_number" integer NOT NULL, "doc" jsonb_text NOT NULL, "author" varchar(255) NULL, "note" text NULL, "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY ("tour_id") REFERENCES "tours" ("id") ON DELETE CASCADE );
CREATE UNIQUE INDEX uniq_tour_versions_tour_number ON tour_versions (tour_id, version_number);
CREATE INDEX idx_tours_org ON tours (org_id);
CREATE UNIQUE INDEX uniq_tours_share_token ON tours (share_token);
CREATE TABLE "resource_folders" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "org_id" integer NOT NULL, "name" varchar(255) NOT NULL, "emoji" varchar(16) NULL, "created_by" integer NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE "resource_labels" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "org_id" integer NOT NULL, "resource_kind" varchar(32) NOT NULL, "resource_id" varchar(64) NOT NULL, "labels" jsonb_text NULL, "updated_by" integer NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE "resource_containments" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "org_id" integer NOT NULL, "child_kind" varchar(32) NOT NULL, "child_id" varchar(64) NOT NULL, "parent_kind" varchar(32) NOT NULL, "parent_id" varchar(64) NOT NULL, "sort_key" varchar(64) NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE "resource_edges" ( "created_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp_with_timezone_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "org_id" integer NOT NULL, "relation" varchar(64) NOT NULL, "source_kind" varchar(32) NOT NULL, "source_id" varchar(64) NOT NULL, "target_kind" varchar(32) NOT NULL, "target_id" varchar(64) NOT NULL, "placement" jsonb_text NULL, FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON DELETE CASCADE ON UPDATE CASCADE );
CREATE UNIQUE INDEX uniq_resource_containment_child ON resource_containments (org_id, child_kind, child_id);
CREATE INDEX idx_resource_containment_parent ON resource_containments (org_id, parent_kind, parent_id);
CREATE UNIQUE INDEX uniq_resource_labels_resource ON resource_labels (org_id, resource_kind, resource_id);
CREATE UNIQUE INDEX uniq_resource_edges_pair ON resource_edges (org_id, relation, source_kind, source_id, target_kind, target_id);
CREATE INDEX idx_resource_edges_target ON resource_edges (org_id, target_kind, target_id);
